// Utility Formatters & Data Helpers
function fmtRpJuta(juta) {
  if (juta === undefined || juta === null || isNaN(juta)) return 'Rp 0';
  if (juta === 0) return 'Rp 0';
  if (juta >= 1000000) {
    return 'Rp ' + (juta / 1000000).toLocaleString('id-ID', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' T';
  }
  if (juta >= 1000) {
    return 'Rp ' + (juta / 1000).toLocaleString('id-ID', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + ' M';
  }
  return 'Rp ' + Math.round(juta).toLocaleString('id-ID') + ' Jt';
}

function fmtInt(n) {
  if (!n && n !== 0) return '0';
  return Number(n).toLocaleString('id-ID');
}

function fmtDec(n, d = 2) {
  if (!n && n !== 0) return '0';
  return Number(n).toLocaleString('id-ID', { minimumFractionDigits: d, maximumFractionDigits: d });
}

function cleanTag(t) {
  if (!t) return '';
  return String(t)
    .replace(/^DPP_/, 'DPP: ')
    .replace(/^Zona_/, '')
    .replace(/^Triwulan_/, 'Triwulan ')
    .replace(/^Investasi_/, 'Investasi ')
    .replace(/_/g, ' ')
    .replace('Prambananan', 'Prambanan');
}

function exportCSV(filename, rows) {
  if (!rows || !rows.length) return;
  const header = ['Tahun', 'Triwulan', 'Provinsi', 'Kabupaten/Kota', 'Kawasan DPP', 'Nilai Realisasi (Juta Rp)', 'Nilai Realisasi (Rupiah)', 'Zona Kepulauan', 'Skala Investasi'];
  const esc = (v) => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const csvContent = [
    header.join(','),
    ...rows.map(r => [
      2025,
      r[0],
      esc(r[1]),
      esc(r[2]),
      esc(r[3] || 'Non-DPP'),
      r[4],
      Math.round((r[4] || 0) * 1000000),
      esc(r[5]),
      esc(r[6])
    ].join(','))
  ].join('\r\n');

  const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

